/* MUTANT llmClient.revert — generated by make-mutants.mjs from src/main/llmClient.ts */
export const MUTANT = "llmClient.revert"
import type { ApiConfig, LLMMessage, LLMToolCall } from '../../../../src/shared/types'

function normalizeBaseURL(raw: string): string {
  const base = raw.trim().replace(/\/+$/, '')
  if (base.endsWith('/chat/completions')) return base
  if (base.endsWith('/chat')) return base + '/completions'
  return base + '/chat/completions'
}

interface ToolCallAcc {
  id: string
  name: string
  args: string
}

/**
 * R2: tool-call ids that the provider did not supply must still be unique.
 *
 * A deterministic fallback (`call_${name}` / `call_${index}`) collides across
 * rounds: two assistant turns that both omit the id for the same tool produce
 * the same string, and the renderer's `replaceToolMessage` then OVERWRITES the
 * previous round's tool reply (it matches on `tool_call_id`). The newest
 * assistant message ends up with an unanswered tool_call and the provider
 * rejects the follow-up with HTTP 400 — the F2 failure coming back through the
 * back door. So fallback ids carry a process-wide sequence, and duplicates are
 * additionally de-duplicated in case a provider repeats an id verbatim.
 */
let fallbackToolCallSeq = 0
const FALLBACK_TOOL_CALL_PREFIX = 'call_auto_'

function uniqueToolId(seen: Set<string>, candidate: string): string {
  let id = candidate
  while (seen.has(id)) id = `${FALLBACK_TOOL_CALL_PREFIX}${++fallbackToolCallSeq}`
  seen.add(id)
  return id
}

function withUniqueToolIds(calls: LLMToolCall[]): LLMToolCall[] {
  return calls
}

export interface CompletedChat {
  finishReason: string | null
  toolCalls: LLMToolCall[]
  text: string
}

/**
 * OpenAI-compatible chat completion client (streaming with SSE parsing,
 * non-streaming fallback). Runs in the main process so the API key never
 * reaches the renderer.
 */
export async function chatComplete(
  config: ApiConfig,
  messages: LLMMessage[],
  tools: unknown[],
  emitChunk: (delta: string) => void,
  abort?: AbortSignal
): Promise<CompletedChat> {
  const url = normalizeBaseURL(config.baseURL)
  const body: Record<string, unknown> = {
    model: config.model,
    messages,
    stream: true
  }
  if (tools.length > 0) body.tools = tools

  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), 5 * 60 * 1000)
  if (abort) {
    abort.addEventListener('abort', () => controller.abort(), { once: true })
  }

  let resp: Response
  try {
    resp = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${config.apiKey}`
      },
      body: JSON.stringify(body),
      signal: controller.signal
    })
  } catch (err) {
    clearTimeout(timer)
    if (abort?.aborted) throw new Error('已取消')
    const e = err as { cause?: { code?: string } }
    if (
      e.cause?.code === 'ECONNREFUSED' ||
      e.cause?.code === 'ENOTFOUND' ||
      e.cause?.code === 'EAI_AGAIN'
    ) {
      throw new Error('网络连接失败，请检查网络或接口地址')
    }
    throw new Error('网络请求失败: ' + (err instanceof Error ? err.message : String(err)))
  }

  if (!resp.ok) {
    clearTimeout(timer)
    let detail = `HTTP ${resp.status}`
    try {
      const text = await resp.text()
      const json = JSON.parse(text) as { error?: { message?: string } | string }
      const msg =
        typeof json.error === 'string'
          ? json.error
          : (json.error?.message ?? json.error?.message ?? '')
      if (msg) detail += ` — ${msg}`
    } catch {
      // keep status only
    }
    throw new Error('API 请求失败: ' + detail)
  }

  const contentType = resp.headers.get('content-type') ?? ''
  const isStream = contentType.includes('text/event-stream')

  if (!isStream || !resp.body) {
    // non-streaming fallback
    const json = (await resp.json()) as NonStreamingResponse
    clearTimeout(timer)
    const choice = json.choices?.[0]
    const text = choice?.message?.content ?? ''
    const toolCalls = mapToolCalls(choice?.message?.tool_calls)
    if (text) emitChunk(text)
    return { finishReason: choice?.finish_reason ?? null, toolCalls, text }
  }

  // SSE streaming
  const reader = resp.body.getReader()
  const decoder = new TextDecoder()
  let buf = ''
  let text = ''
  const calls: ToolCallAcc[] = []
  let finishReason: string | null = null

  try {
    for (;;) {
      const { done, value } = await reader.read()
      if (done) break
      buf += decoder.decode(value, { stream: true })
      let idx: number
      while ((idx = buf.indexOf('\n')) >= 0) {
        const line = buf.slice(0, idx).replace(/\r$/, '')
        buf = buf.slice(idx + 1)
        if (!line.startsWith('data:')) continue
        const payload = line.slice(5).trim()
        if (!payload || payload === '[DONE]') {
          if (payload === '[DONE]') finishReason = finishReason ?? 'stop'
          continue
        }
        let evt: SseEvent
        try {
          evt = JSON.parse(payload) as SseEvent
        } catch {
          continue
        }
        const choice = evt.choices?.[0]
        if (!choice) continue
        const delta = choice.delta
        if (delta?.content) {
          text += delta.content
          emitChunk(delta.content)
        }
        if (delta?.tool_calls) {
          for (const tc of delta.tool_calls) {
            const i = tc.index ?? 0
            calls[i] = calls[i] ?? { id: '', name: '', args: '' }
            if (tc.id) calls[i].id += tc.id
            if (tc.function?.name) calls[i].name += tc.function.name
            if (tc.function?.arguments) calls[i].args += tc.function.arguments
          }
        }
        if (choice.finish_reason) {
          finishReason = choice.finish_reason
        }
      }
    }
  } catch (err) {
    clearTimeout(timer)
    if (abort?.aborted) throw new Error('已取消')
    throw new Error('流式读取中断: ' + (err instanceof Error ? err.message : String(err)))
  }
  clearTimeout(timer)

  const toolCalls = withUniqueToolIds(
    calls
      .filter((c) => c.name)
      .map((c): LLMToolCall => ({
        // a stable-but-unique fallback: `call_auto_<seq>` (see R2 note above)
        id: c.id || `call_${c.name}`,
        type: 'function',
        function: { name: c.name, arguments: c.args || '{}' }
      }))
  )
  return { finishReason, toolCalls, text }
}

function mapToolCalls(
  tcs?: Array<{ id?: string; function?: { name?: string; arguments?: string } }>
): LLMToolCall[] {
  if (!tcs) return []
  return withUniqueToolIds(
    tcs.map((tc, i): LLMToolCall => ({
      id: tc.id ?? `call_${i}`,
      type: 'function',
      function: { name: tc.function?.name ?? '', arguments: tc.function?.arguments ?? '{}' }
    }))
  )
}

interface SseEvent {
  choices?: Array<{
    delta?: {
      content?: string
      tool_calls?: Array<{
        index?: number
        id?: string
        function?: { name?: string; arguments?: string }
      }>
    }
    finish_reason?: string | null
  }>
}

interface NonStreamingResponse {
  choices?: Array<{
    message?: {
      content?: string
      tool_calls?: Array<{ id?: string; function?: { name?: string; arguments?: string } }>
    }
    finish_reason?: string | null
  }>
}

/** Validate connectivity + credentials with a cheap request. */
export async function testApi(
  config: ApiConfig
): Promise<{ ok: boolean; message: string; models?: string[] }> {
  const base = config.baseURL.trim().replace(/\/+$/, '')
  if (!base) return { ok: false, message: '请填写接口地址' }
  if (!config.model.trim()) return { ok: false, message: '请填写模型名称' }
  if (!config.apiKey.trim()) return { ok: false, message: '请填写 API Key' }

  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(), 15 * 1000)
  try {
    // discover model list via GET /models (many providers expose it)
    const url = base.endsWith('/models') ? base : base + '/models'
    try {
      const resp = await fetch(url, {
        method: 'GET',
        headers: { Authorization: `Bearer ${config.apiKey}` },
        signal: controller.signal
      })
      if (resp.ok) {
        const json = (await resp.json()) as { data?: Array<{ id?: string }> }
        const models = (json.data ?? []).map((m) => m.id).filter((x): x is string => Boolean(x))
        if (models.length > 0) {
          return { ok: true, message: '连接成功，服务可用', models }
        }
        return { ok: true, message: '连接成功，服务可用' }
      }
    } catch {
      // /models unavailable → fall through to 1-token completion
    }

    // fallback: 1-token completion
    const chatResp = await fetch(normalizeBaseURL(base), {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${config.apiKey}` },
      body: JSON.stringify({
        model: config.model,
        messages: [{ role: 'user', content: 'hi' }],
        max_tokens: 1
      }),
      signal: controller.signal
    })
    if (chatResp.ok) return { ok: true, message: '连接成功，服务可用' }
    let detail = `HTTP ${chatResp.status}`
    let errorMsg = ''
    try {
      const json = (await chatResp.json()) as { error?: { message?: string } | string }
      const e = typeof json.error === 'string' ? json.error : json.error?.message
      if (e) {
        errorMsg = e
        detail += ` — ${e}`
      }
    } catch {
      // ignore
    }
    // extract "supported ... are A, B, C" → offer as model suggestions
    const models = extractSupportedModels(errorMsg)
    if (models.length > 0 && models.includes(config.model) === false) {
      detail = `模型名称无效，请选择：${models.join('、')}`
    }
    return { ok: false, message: detail, models: models.length ? models : undefined }
  } catch (err) {
    return { ok: false, message: '连接失败: ' + (err instanceof Error ? err.message : String(err)) }
  } finally {
    clearTimeout(timer)
  }
}

/** pull model names out of a provider "supported ... are A, B, and C" message */
function extractSupportedModels(msg: string): string[] {
  const m =
    /supported\s+API\s+model\s+names?\s+are\s+(.+)/i.exec(msg) ??
    /model names?\s+are\s+(.+)/i.exec(msg)
  if (!m) return []
  const chunk = m[1]
    .replace(/[.\s]+$/, '')
    .split(/,|, and |\s+and\s+/)
    .map((s) => s.trim())
    .filter((s) => /^[A-Za-z0-9._:/-]+$/.test(s))
  return chunk
}
